WITH prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) AS prev_started_at FROM sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT customer_id, ROUND(AVG(new_group_flag), 2) AS avg_new_group_flag, COUNT_IF(browser = 'Chrome') AS chrome_events, SUM(new_group_flag) FILTER (WHERE device = 'tablet') AS tablet_total_new_group_flag, GROUPING_ID() AS gid FROM sessionized GROUP BY CUBE (customer_id) HAVING ROUND(AVG(new_group_flag), 2) < 1000000;
